// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));

        // Call setOwner as the current owner
        vm.prank(c.owner());
        (bool success) = c.setOwner(_owner);

        assertTrue(success && c.owner() == (_owner));
    }
}

